<?php
namespace App\Http\Controllers;
use App\Models\{Book,Category,Publisher,BookRating,BookComment,Order,OrderItem,BookAccess,User,PointLedger};
use App\Services\StoreService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Storage;
class StoreController extends Controller {
 public function home(){return view('home',['latestBooks'=>Book::with('category')->latest('id')->limit(4)->get(),'categories'=>Category::orderBy('name')->get()]);}
 public function books(Request $r){$q=Book::with('category')->when($r->search,fn($x)=>$x->where(fn($y)=>$y->where('title','like','%'.$r->search.'%')->orWhere('author','like','%'.$r->search.'%')))->when($r->category,fn($x)=>$x->where('category_id',(int)$r->category))->orderByDesc('id')->paginate(12)->withQueryString();return view('books.index',['books'=>$q,'categories'=>Category::orderBy('name')->get(),'search'=>$r->search,'categoryId'=>(int)$r->category]);}
 public function showBook(Request $r,Book $book){$book->load(['category','publisher']);$avg=(float)($book->ratings()->avg('rating')??$book->rating??0);$userRating=auth()->check()?(int)(BookRating::where(['book_id'=>$book->id,'user_id'=>auth()->id()])->value('rating')??0):0;$hasAccess=auth()->check()&&BookAccess::where(['book_id'=>$book->id,'user_id'=>auth()->id()])->exists();$comments=BookComment::with('user')->where('book_id',$book->id)->latest('created_at')->get();return view('books.show',compact('book','avg','userRating','hasAccess','comments'));}
 public function rate(Request $r,Book $book){$d=$r->validate(['rating'=>'required|integer|min:1|max:5']);BookRating::updateOrCreate(['book_id'=>$book->id,'user_id'=>auth()->id()],['rating'=>$d['rating']]);StoreService::awardPoints(auth()->id(),'rating:'.$book->id,15,'تقييم كتاب');return back()->withFragment('rating');}
 public function comment(Request $r,Book $book){$d=$r->validate(['body'=>'required|string|max:2000']);$c=BookComment::create(['book_id'=>$book->id,'user_id'=>auth()->id(),'body'=>$d['body']]);StoreService::awardPoints(auth()->id(),'comment:'.$c->id,10,'نشر تعليق');return back()->withFragment('comments');}
 public function addCart(Request $r){$d=$r->validate(['book_id'=>'required|integer','quantity'=>'required|integer|min:1']);$b=Book::findOrFail($d['book_id']);session()->put('cart.'. $b->id,min($d['quantity'],$b->stock));return redirect()->route('cart');}
 public function cart(Request $r){if($r->isMethod('post')){if($r->action==='remove')session()->forget('cart.'.$r->book_id);elseif($r->action==='update'){ $b=Book::find($r->book_id);$q=max(0,(int)$r->quantity);if(!$b||$q===0||$b->stock<1)session()->forget('cart.'.$r->book_id);else session()->put('cart.'.$r->book_id,min($q,$b->stock));}return redirect()->route('cart');}$cart=session('cart',[]);$items=Book::whereIn('id',array_keys($cart))->orderByDesc('id')->get()->map(function($b)use($cart){$b->quantity=(int)$cart[$b->id];return $b;});$total=$items->sum(fn($b)=>$b->price*$b->quantity);return view('cart',compact('items','total'));}
 public function checkout(){if(!StoreService::cartCount())return redirect()->route('cart');$cart=session('cart',[]);$items=Book::whereIn('id',array_keys($cart))->get()->map(function($b)use($cart){$b->quantity=(int)$cart[$b->id];return $b;});return view('checkout',compact('items'));}
 public function placeOrder(Request $r){$d=$r->validate(['customer_name'=>'required','address'=>'required']);$cart=session('cart',[]);$items=Book::whereIn('id',array_keys($cart))->lockForUpdate()->get();if($items->count()!==count($cart))return back()->with('error','بعض الكتب في العربة لم تعد متاحة.');try{$order=DB::transaction(function()use($d,$items,$cart){$total=0;foreach($items as $b){$q=(int)$cart[$b->id];if($q>$b->stock)throw new \RuntimeException('الكمية المطلوبة من كتاب «'.$b->title.'» غير متاحة.');$total+=$b->price*$q;}$order=Order::create(['user_id'=>auth()->id(),'customer_name'=>$d['customer_name'],'customer_email'=>auth()->user()->email,'whatsapp'=>'01121771193','address'=>$d['address'],'total'=>$total,'payment_method'=>'instapay','status'=>'pending']);foreach($items as $b){$q=(int)$cart[$b->id];OrderItem::create(['order_id'=>$order->id,'book_id'=>$b->id,'title'=>$b->title,'price'=>$b->price,'quantity'=>$q]);$b->decrement('stock',$q);}StoreService::awardPoints(auth()->id(),'order:'.$order->id,50,'إنشاء طلب شراء');return $order;});session()->forget('cart');$lines=['طلب جديد رقم #'.$order->id,'الاسم: '.$order->customer_name,'العنوان: '.$order->address,'واتساب: 01121771193','','تفاصيل الطلب:'];foreach($order->items as $i)$lines[]=$i->title.' × '.$i->quantity.' = '.number_format($i->price*$i->quantity,2).' جنيه';$lines[]='';$lines[]='الإجمالي: '.number_format($order->total,2).' جنيه';$lines[]='يرجى تحويل المبلغ عبر InstaPay إلى 01121771193 وإرسال Screenshot التحويل في هذه المحادثة.';return redirect()->away('https://web.whatsapp.com/send?phone=201121771193&text='.rawurlencode(implode("\n",$lines)));}catch(\Throwable $e){return back()->with('error',$e->getMessage());}}
 public function myBooks(){ $books=Book::whereIn('id',BookAccess::where('user_id',auth()->id())->pluck('book_id'))->get();return view('my-books',compact('books')); }
 public function myOrders(){ $orders=Order::with('items')->where('user_id',auth()->id())->latest()->get();return view('my-orders',compact('orders')); }
 public function publishers(Request $r){$publishers=Publisher::withCount('books')->orderBy('name')->get();$books=Book::with('publisher')->when($r->search,fn($q)=>$q->where(fn($x)=>$x->where('title','like','%'.$r->search.'%')->orWhereHas('publisher',fn($p)=>$p->where('name','like','%'.$r->search.'%'))))->when((int)$r->publisher,fn($q)=>$q->where('publisher_id',(int)$r->publisher))->orderByDesc('id')->get();return view('publishers',compact('publishers','books'));}
 public function statistics(){return view('statistics',['books'=>Book::count(),'categories'=>Category::count(),'publishers'=>Publisher::count(),'totalOrders'=>Order::count(),'sold'=>OrderItem::sum('quantity')]);}
 public function leaderboard(){ $leaders=User::where('role','user')->withSum('pointsLedger as points','points')->withCount('pointsLedger as activities')->orderByDesc('points')->orderBy('id')->limit(50)->get();$current=$leaders->firstWhere('id',auth()->id());return view('leaderboard',compact('leaders','current'));}
 public function orderSuccess(Order $order){abort_unless(auth()->id()===$order->user_id,403);return view('order-success',compact('order'));}
}